llamadas.contenido:
{
  "title": "Historia de Usuario (HU) - Reservar un ejemplar desde la web para recogerlo en el mostrador",
  "role": "Persona socia de la Biblioteca Municipal de Villaficticia",
  "action": "Reservar un ejemplar desde la web para recogerlo en el mostrador",
  "benefit": "Acceder a la reserva de un ejemplar de título y sede de recogida, con la garantía de que se recoge dentro de los 48 horas, y evitar sanciones por no recoger el ejemplar dentro del plazo establecido.",
  "description": "Un socio de la biblioteca quiere reservar un ejemplar desde la web para recogerlo en el mostrador. El proceso debe incluir la solicitud, validación de la reserva, gestión del estado de la reserva y notificación cuando se recoge o caduca.",
  "business_goal": "Facilitar el acceso a la reserva de ejemplares para personas socias, garantizando que se recoge dentro del plazo establecido y evitando sanciones por no recoger el ejemplar dentro de los 48 horas.",
  "scope_includes": [
    "Solicitud de reserva desde la web",
    "Validación de la reserva en base a reglas de negocio y políticas",
    "Cálculo del estado de la reserva (pendiente, disponible, recogida, caducada, cancelada)",
    "Notificación de recogida o caducación"
  ],
  "scope_excludes": [
    "Renovaciones de préstamos que no estén relacionadas con reservas",
    "Reservas en otros títulos o categorías no contempladas",
    "Servicios externos o pagos de acceso"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Solicitud de reserva",
      "given": ["La persona socia accede a la web y selecciona el título y sede de recogida.", "La reserva se solicita con el nombre completo y el código de carné vigente."],
      "when": ["La persona socia accede a la web y selecciona el título y sede de recogida.", "La reserva se solicita con el nombre completo y el código de carné vigente."],
      "then": ["La reserva se registrará en el sistema y se mostrará en la cola de reservas."]
    },
    {
      "id": "CA-02",
      "title": "Validación de la reserva",
      "given": ["La reserva tiene estado 'pendiente' y el título y sede de recogida están disponibles.", "La persona socia ya tiene 3 reservas activas."],
      "when": ["La reserva es registrada y se muestra en la cola de reservas.", "La persona socia tiene 3 reservas activas."],
      "then": ["La reserva se procesa y se bloquea durante 48 horas para la persona socia."]
    },
    {
      "id": "CA-03",
      "title": "Notificación de recogida",
      "given": ["El ejemplar se recoge en el mostrador dentro de los 48 horas.", "La persona socia se encabeza de la cola de reservas."],
      "when": ["El ejemplar se recoge en el mostrador dentro de los 48 horas.", "La persona socia se encabeza de la cola de reservas."],
      "then": ["La reserva se convierte en préstamo y se notifica a la persona socia."]
    },
    {
      "id": "CA-04",
      "title": "Sanción por no recoger",
      "given": ["El ejemplar no se recoge dentro de los 48 horas.", "La persona socia no se encabeza de la cola de reservas."],
      "when": ["El ejemplar no se recoge dentro de los 48 horas.", "La persona socia no se encabeza de la cola de reservas."],
      "then": ["La reserva caduca y se pasa a la siguiente persona de la cola. La persona socia recibe una notificación de sanción."]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Solo pueden reservar las personas socias con carné vigente y sin sanción activa que impida reservar."
    },
    {
      "id": "RN-RES-02",
      "description": "Cada persona socia puede tener un máximo de 3 reservas activas. Se considera activa la reserva en estado «pendiente» o «disponible para recoger»."
    },
    {
      "id": "RN-RES-03",
      "description": "La reserva se hace sobre un título y una sede de recogida. El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "id": "RN-RES-04",
      "description": "Las reservas de un mismo título se atienden por estricto orden de llegada (cola de reservas)."
    },
    {
      "id": "RN-RES-05",
      "description": "Cuando el ejemplar queda disponible en la sede de recogida, se bloquea durante 48 horas para la persona socia que encabeza la cola, y se le notifica (ver DOC-10)."
    },
    {
      "id": "RN-RES-06",
      "description": "Si el ejemplar no se recoge en esas 48 horas, la reserva caduca, el ejemplar pasa a la siguiente persona de la cola y la reserva cuenta como «no recogida» a efectos de RN-SAN-04."
    },
    {
      "id": "RN-RES-07",
      "description": "La persona socia puede cancelar una reserva en cualquier momento antes de recogerla, sin penalización."
    },
    {
      "id": "RN-RES-08",
      "description": "Mientras exista una reserva pendiente sobre un título, ningún préstamo de ese título puede renovarse (artículo 5 de DOC-01)."
    },
    {
      "id": "RN-RES-09",
      "description": "No se pueden reservar obras de referencia ni títulos de los que la persona socia ya tenga un ejemplar en préstamo."
    },
    {
      "id": "RN-RES-10",
      "description": "Las personas con carné infantil pueden reservar solo títulos de la colección infantil y juvenil, con el mismo máximo de 3 reservas activas."
    }
  ],
  "assumptions": [
    "La persona socia tiene un carné vigente y no está sancionada.",
    "El sistema garantiza la disponibilidad de ejemplares en la sede de recogida.",
    "La persona socia tiene conocimiento de los límites de reservas y de las reglas aplicables."
  ],
  "constraints": [
    "No se puede reservar un título que esté prohibido por la persona socia.",
    "No se pueden renovar préstamos que estén asociados a reservas pendientes."
  ],
  "dependencies": [
    "La validación de la reserva depende del estado de la cola de reservas.",
    "La notificación de recogida depende del estado de la reserva y de la disponibilidad del ejemplar."
  ],
  "alternate_flows": [
    "Si el ejemplar no se recoge dentro de los 48 horas, la reserva caduca y se pasa a la siguiente persona de la cola.",
    "Si la persona socia no se encabeza de la cola, la reserva se vuelve a la cola y se regresa a la sección de reservas."
  ],
  "exceptions": [
    "Las reservas no recogidas reiteradas no se consideran en el proceso de reserva normal.",
    "Las personas con carné infantil tienen límites de reserva específicos."
  ],
  "related_features": [
    "Prestamos de ejemplares",
    "Sanciones por no recoger ejemplares",
    "Renovaciones de préstamos"
  ],
  "priority": "Should",
  "sources": [
    {
      "kind": "rag",
      "ref": "DOC-02",
      "excerpt": "RN-RES-01. Solo pueden reservar las personas socias con carné vigente y sin sanción activa que impida reservar (ver RN-SAN-03 y RN-SAN-04 en DOC-03)."
    },
    {
      "kind": "rag",
      "ref": "DOC-06",
      "excerpt": "El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "kind": "rag",
      "ref": "DOC-01",
      "excerpt": "Cada persona socia puede tener en préstamo simultáneo un máximo de 8 ejemplares."
    },
    {
      "kind": "rag",
      "ref": "DOC-20",
      "excerpt": "Se acuerda también que el aviso de reserva caducada informe del número de reservas no recogidas acumuladas, para que la persona socia pueda evitar la sanción."
    }
  ],
  "open_questions": [
    "¿Qué ocurre si la persona socia no tiene un carné vigente o tiene sanción activa?",
    "¿Cómo se maneja la cota de reservas activas si la persona socia supera el límite de 3 reservas?",
    "¿Cómo se notifica la persona socia cuando la reserva caduca y se le informa de la sanción?"
  ]
}
